using HRIS.Api.DTOs.Laptop; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/laptops")][Authorize] public class LaptopsController:ControllerBase { private readonly ILaptopService _service; public LaptopsController(ILaptopService service)=>_service=service; [HttpGet] public async Task<IActionResult> Get()=>Ok(await _service.GetAsync(User.ToUserContext())); [HttpPost] public async Task<IActionResult> Create(LaptopCreateDto dto)=>Ok(await _service.CreateAsync(dto,User.ToUserContext())); [HttpPost("{id:int}/status")][Authorize(Roles="HR,Support")] public async Task<IActionResult> Status(int id,[FromQuery]string status,[FromQuery]string? note=null){await _service.UpdateStatusAsync(id,status,note,User.ToUserContext());return NoContent();} }
